const inputData = $input.item.json;
const config = $('Set Sport Config').item.json;
const sportId = config.basketballSportId;
const sportName = 'Basketball';

// 籃球所有常見專屬賽事事件欄位 keyMap
const keyMap = {
  "First to score points": "firstToScore",
  "20 points race (3rd quarter)": "race20Q3",
  "100 points race": "race100",
  "75 points race": "race75",
  "50 points race": "race50",
};

const events = [];
const sports = inputData.reply.sports;

for (const sid in sports) {
  if (sid !== sportId) continue;

  const sport = sports[sid];
  for (const champId in sport.chmps) {
    const championship = sport.chmps[champId];

    if (!championship.name_ch || championship.name_ch.includes('Cyberbasketball.') || championship.name_ch.includes('stats.') || championship.name_ch.includes('Stats.') || championship.name_ch.includes('statistics.')) continue; // skip Cyberfootball
    // 刪去 sportName 前綴，取得 leagueName
    const leagueName = championship.name_ch.replace(new RegExp(sportName + '\\.\\s*', 'i'), '').trimStart();
    for (const eventId in championship.evts) {
      const evt = championship.evts[eventId];

      // 時間修正
      const date = new Date(evt.date_ev.replace(" ", "T") + "Z");
      date.setHours(date.getHours() + 8);
      const eventDate = date.toISOString().slice(0, 10);
      const eventTime = date.toISOString().slice(0, 19).replace('T', ' ');

      // 初始化籃球欄位（全部專用欄位清空）
      const event = {
        eventId: evt.id_ev,
        eventDate: eventDate,
        eventDateTime: eventTime,
        leagueGroupId: championship.id_ch,
        leagueId: championship.cn_ch,
        league: leagueName,
        islive: evt.hasOwnProperty('is_live') ? evt.is_live : '0',
        home: evt.name_ht,
        away: evt.name_at,
        q1score: '',  
        q2score: '',  
        q3score: '',  
        q4score: '',  
        ot1Score: '',
        ot2Score: '',
        ot3Score: '',
        finalscore: evt.sc_ev,
        ...Object.keys(keyMap).reduce((acc, k) => { acc[keyMap[k]] = ''; return acc; }, {}),
      };

      // 處理四節分數
      if (evt.sc_ext_ev) {
        const periods = evt.sc_ext_ev.split(',');
        event.q1score = periods[0] ? periods[0].trim() : '';
        event.q2score = periods[1] ? periods[1].trim() : '';
        event.q3score = periods[2] ? periods[2].trim() : '';
        event.q4score = periods[3] ? periods[3].trim() : '';
        // 如果有 (OT) 欄位，延長賽分數往後排
        if (evt.sc_com_ev && evt.sc_com_ev.trim() === '(OT)') {
          if(periods.length === 3)
          {
            event.q3score = '';
            event.q4score = '';
            event.ot1Score = periods[2] ? periods[2].trim() : '';
          }
          else
          {
             // periods[4] 之後都是延長賽分數
            for (let i = 4; i < periods.length; i++) {
              event[`ot${i - 3}Score`] = periods[i] ? periods[i].trim() : '';
            }
          }
        }
      }

      // ext 部分根據 name_ext 對應 keyMap，直接塞 value_ext
      if (Array.isArray(evt.ext)) {
        evt.ext.forEach(extItem => {
          const simpleKey = keyMap[extItem.name_ext];
          if (simpleKey) {
            event[simpleKey] = extItem.value_ext;
          }
        });
      }

      events.push(event);
    }
  }
}
return events;

